from pathlib import Path
import base64

ROOT = Path(__file__).resolve().parent.parent

ICON_B64 = ''''''

# Write the approved transparent black coffee-machine icon.
(ROOT / 'machinepark-coffee-device-icon.png').write_bytes(base64.b64decode(ICON_B64))

index_path = ROOT / 'index.html'
text = index_path.read_text(encoding='utf-8')
css_anchor = ".kpi .dot{float:right;width:11px;height:11px;border-radius:50%;background:var(--brand2);margin-top:4px}"
css_add = css_anchor + ".kpi-device-icon{float:right;width:34px;height:34px;object-fit:contain;margin:-2px -2px 0 10px;opacity:.96}"
if 'kpi-device-icon' not in text:
    if css_anchor not in text:
        raise SystemExit('KPI CSS anchor niet gevonden')
    text = text.replace(css_anchor, css_add, 1)

old_kpi = '<div class="kpi"><span class="dot"></span><div class="label">Actieve toestellen</div><div class="value" id="kpiDevices">0</div><div class="hint">in servicebeheer</div></div>'
new_kpi = '<div class="kpi"><img class="kpi-device-icon" src="/machinepark-coffee-device-icon.png" alt="" aria-hidden="true"><div class="label">Actieve toestellen</div><div class="value" id="kpiDevices">0</div><div class="hint">in servicebeheer</div></div>'
if old_kpi in text:
    text = text.replace(old_kpi, new_kpi, 1)
elif new_kpi not in text:
    raise SystemExit('KPI Actieve toestellen niet gevonden')

text = text.replace('v1.60 • Zoeken op locatie of toestelnummer', 'v1.61 • Koffietoestelicoon dashboard')
index_path.write_text(text, encoding='utf-8')

sw_path = ROOT / 'sw.js'
sw = sw_path.read_text(encoding='utf-8')
sw = sw.replace("machinepark-v1.60-location-device-search", "machinepark-v1.61-dashboard-coffee-icon")
sw = sw.replace("'/machinepark-logo.svg']", "'/machinepark-logo.svg','/machinepark-coffee-device-icon.png']")
sw_path.write_text(sw, encoding='utf-8')

package_path = ROOT / 'package.json'
pkg = package_path.read_text(encoding='utf-8').replace('"version": "1.60.0"', '"version": "1.61.0"')
package_path.write_text(pkg, encoding='utf-8')

test_path = ROOT / 'tests/build-smoke.test.mjs'
test = test_path.read_text(encoding='utf-8')
if "'machinepark-coffee-device-icon.png'," not in test:
    test = test.replace("    '<title>Machinepark</title>',", "    '<title>Machinepark</title>',\n    'machinepark-coffee-device-icon.png',\n    'kpi-device-icon',", 1)
test = test.replace('machinepark-v1.60-location-device-search', 'machinepark-v1.61-dashboard-coffee-icon')
test_path.write_text(test, encoding='utf-8')

validator_path = ROOT / 'scripts/build-machinepark.py'
validator = validator_path.read_text(encoding='utf-8')
if 'dashboard koffietoestelicoon' not in validator:
    validator = validator.replace('    "operationeel dashboard": "dashboardProfessional",', '    "operationeel dashboard": "dashboardProfessional",\n    "dashboard koffietoestelicoon": "machinepark-coffee-device-icon.png",', 1)
validator = validator.replace('machinepark-v1.60-location-device-search', 'machinepark-v1.61-dashboard-coffee-icon')
validator_path.write_text(validator, encoding='utf-8')
